seed_files.include/config.h:
#pragma once
constexpr int LED_PIN = 2;
constexpr int SENSOR_PIN = 34;
constexpr unsigned long PERIOD_MS = 100;

seed_files.src/main.cpp:
#include <Arduino.h>
#include <missing_config.h>
#include <logic.h>
unsigned long lastSample = 0;
void setup() { Serial.begin(115200); pinMode(LED_PIN, OUTPUT); }
void loop() {
 const unsigned long now = millis();
 if (now - lastSample >= PERIOD_MS) {
  lastSample = now;
  const int sample = clampSample(analogRead(SENSOR_PIN));
  digitalWrite(LED_PIN, sample > 2000 ? HIGH : LOW);
 }
}

